# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: test-full-system.ps1

# ── Config ────────────────────────────────────────────────────────────────────
$GATEWAY      = "http://localhost:8080"
$AUTH         = "http://localhost:9000"
$PAYMENT      = "http://localhost:8003"
$MERCHANT     = "http://localhost:8001"
$CUSTOMER     = "http://localhost:8002"
$FRAUD        = "http://localhost:8004"
$BANK         = "http://localhost:8006"
$LEDGER       = "http://localhost:8007"
$NOTIFICATION = "http://localhost:8008"

$SECRET_KEY      = "sk_test_123"
$PUBLISHABLE_KEY = "pk_test_123"

$script:pass = 0
$script:fail = 0
$script:warn = 0

function Write-Header { param([string]$t)
    Write-Host "`n$("─"*70)" -ForegroundColor Cyan
    Write-Host "  $t" -ForegroundColor Cyan
    Write-Host "$("─"*70)" -ForegroundColor Cyan
}
function Pass  { param([string]$t) { Write-Host "  ✓ $t" -ForegroundColor Green;  $script:pass++ } }
function Fail  { param([string]$t) { Write-Host "  ✗ $t" -ForegroundColor Red;    $script:fail++ } }
function Warn  { param([string]$t) { Write-Host "  ⚠ $t" -ForegroundColor Yellow; $script:warn++ } }
function Info  { param([string]$t) { Write-Host "    → $t" -ForegroundColor Gray } }
function Data  { param([string]$k, $v) { Write-Host "    $k : " -NoNewline -ForegroundColor White; Write-Host $v -ForegroundColor DarkGray } }

Clear-Host
Write-Host "`n╔$("═"*68)╗" -ForegroundColor Cyan
Write-Host "║        PAYMENT GATEWAY — FULL SYSTEM TEST                        ║" -ForegroundColor Cyan
Write-Host "╚$("═"*68)╝`n" -ForegroundColor Cyan

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 1 — HEALTH CHECKS (all 8 services)
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 1 · HEALTH CHECKS"

$services = @(
    @{ name="Auth Service";         url="$AUTH/health" },
    @{ name="Fraud Service";        url="$FRAUD/health" },
    @{ name="Bank Connector";       url="$BANK/health" },
    @{ name="Ledger Service";       url="$LEDGER/health" },
    @{ name="Notification Service"; url="$NOTIFICATION/health" },
    @{ name="Payment Service";      url="$PAYMENT/health" },
    @{ name="Merchant Service";     url="$MERCHANT/health" },
    @{ name="Customer Service";     url="$CUSTOMER/health" },
    @{ name="API Gateway";          url="$GATEWAY/health" }
)

foreach ($svc in $services) {
    try {
        $r = Invoke-RestMethod -Uri $svc.url -Method GET -TimeoutSec 5
        Pass "$($svc.name) healthy"
    } catch {
        Fail "$($svc.name) UNREACHABLE — $($svc.url)"
    }
}

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 2 — AUTH SERVICE
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 2 · AUTH SERVICE — TOKEN GENERATION"

# Merchant JWT
$script:merchantJwt = $null
try {
    $r = Invoke-RestMethod -Uri "$AUTH/token" -Method POST -ContentType "application/json" -Body (@{
        sub    = "merchant_test_001"
        email  = "merchant@testshop.com"
        roles  = @("merchant")
        scopes = @("payment:read","payment:refund","payment:void","payment:capture","webhook:manage")
    } | ConvertTo-Json)
    $script:merchantJwt = $r.access_token
    Pass "Merchant JWT issued"
    Data "Token (truncated)" "$($script:merchantJwt.Substring(0,40))..."
} catch { Fail "Merchant JWT failed: $($_.ErrorDetails.Message)" }

# Customer JWT
$script:customerJwt = $null
try {
    $r = Invoke-RestMethod -Uri "$AUTH/token" -Method POST -ContentType "application/json" -Body (@{
        sub    = "customer_test_001"
        email  = "customer@gmail.com"
        roles  = @("customer")
        scopes = @("payment_session:create","payment_method:tokenize","payment_intent:confirm_own")
    } | ConvertTo-Json)
    $script:customerJwt = $r.access_token
    Pass "Customer JWT issued"
} catch { Fail "Customer JWT failed: $($_.ErrorDetails.Message)" }

# Admin JWT
$script:adminJwt = $null
try {
    $r = Invoke-RestMethod -Uri "$AUTH/token" -Method POST -ContentType "application/json" -Body (@{
        sub    = "admin_test_001"
        email  = "admin@platform.com"
        roles  = @("admin")
        scopes = @("*")
    } | ConvertTo-Json)
    $script:adminJwt = $r.access_token
    Pass "Admin JWT issued"
} catch { Fail "Admin JWT failed: $($_.ErrorDetails.Message)" }

# Verify a token
if ($script:merchantJwt) {
    try {
        $v = Invoke-RestMethod -Uri "$AUTH/verify" -Method POST -ContentType "application/json" `
            -Body (@{ token = $script:merchantJwt } | ConvertTo-Json)
        Pass "Token verification working"
        Data "Subject" $v.sub
        Data "Roles"   ($v.roles -join ", ")
    } catch { Fail "Token verify failed" }
}

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 3 — FRAUD SERVICE (direct)
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 3 · FRAUD SERVICE — DIRECT SCORING"

# Low-risk card
try {
    $r = Invoke-RestMethod -Uri "$FRAUD/score" -Method POST -ContentType "application/json" -Body (@{
        payment_id   = "pi_fraud_test_low"
        merchant_id  = "m_123"
        amount       = 2500
        currency     = "usd"
        card_number  = "4242424242424242"
        customer_id  = "cust_001"
        ip_address   = "192.168.1.1"
        card_country = "US"
    } | ConvertTo-Json)
    Pass "Low-risk score returned"
    Data "Score"      $r.score
    Data "Decision"   $r.decision
    Data "Risk level" $r.risk_level
} catch { Fail "Fraud score (low risk) failed: $($_.ErrorDetails.Message)" }

# High-risk card
try {
    $r = Invoke-RestMethod -Uri "$FRAUD/score" -Method POST -ContentType "application/json" -Body (@{
        payment_id   = "pi_fraud_test_high"
        merchant_id  = "m_123"
        amount       = 999999
        currency     = "usd"
        card_number  = "4000000000000002"
        customer_id  = "cust_suspicious"
        ip_address   = "10.0.0.1"
        card_country = "XX"
    } | ConvertTo-Json)
    Pass "High-risk score returned"
    Data "Score"    $r.score
    Data "Decision" $r.decision
} catch { Warn "High-risk score test skipped: $($_.ErrorDetails.Message)" }

# Fraud stats
try {
    $r = Invoke-RestMethod -Uri "$FRAUD/stats" -Method GET
    Pass "Fraud stats available"
    Data "Total scored"  $r.total_scored
    Data "Blocked"       $r.blocked
} catch { Warn "Fraud stats not available" }

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 4 — BANK CONNECTOR (direct)
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 4 · BANK CONNECTOR — DIRECT"

try {
    $r = Invoke-RestMethod -Uri "$BANK/health" -Method GET
    Pass "Bank connector responding"
    if ($r.stripe_connected) { Data "Stripe connected" $r.stripe_connected }
} catch { Fail "Bank connector unreachable" }

try {
    $r = Invoke-RestMethod -Uri "$BANK/stats" -Method GET
    Pass "Bank connector stats"
    Data "Total processed" $r.total_processed
    Data "Circuit breaker" $r.circuit_breaker_state
} catch { Warn "Bank connector stats not available" }

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 5 — LEDGER SERVICE (direct)
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 5 · LEDGER SERVICE — ACCOUNTS & BALANCE"

try {
    $r = Invoke-RestMethod -Uri "$LEDGER/accounts" -Method GET
    Pass "System accounts retrieved"
    foreach ($acc in $r) {
        Data "$($acc.account_id)" "balance=$($acc.balance) $($acc.currency)"
    }
} catch { Warn "Accounts endpoint not available" }

try {
    $r = Invoke-RestMethod -Uri "$LEDGER/accounts/acc_platform" -Method GET
    Pass "Platform account details"
    Data "Balance"  $r.balance
    Data "Currency" $r.currency
} catch { Warn "Platform account lookup skipped" }

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 6 — NOTIFICATION SERVICE (direct)
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 6 · NOTIFICATION SERVICE — DIRECT"

# Stats before
try {
    $r = Invoke-RestMethod -Uri "$NOTIFICATION/stats" -Method GET
    Pass "Notification stats"
    Data "Total sent"    $r.total_notifications
    Data "Webhooks"      $r.total_webhooks
} catch { Fail "Notification stats failed" }

# Fire a test event directly
$script:testPaymentId = "pi_direct_$(Get-Date -Format 'yyyyMMddHHmmss')"
try {
    $r = Invoke-RestMethod -Uri "$NOTIFICATION/notify" -Method POST -ContentType "application/json" -Body (@{
        event          = "payment.captured"
        payment_id     = $script:testPaymentId
        merchant_id    = "m_123"
        amount         = 49.99
        currency       = "usd"
        customer_email = "customer@gmail.com"
        customer_name  = "Jane Smith"
        customer_phone = "+15551234567"
        merchant_email = "merchant@testshop.com"
    } | ConvertTo-Json)
    Pass "Direct notification dispatched"
    Data "Queued"   $r.notifications_queued
    Data "Channels" ($r.channels -join ", ")
} catch { Fail "Direct notification failed: $($_.ErrorDetails.Message)" }

# Retrieve by payment id
try {
    $r = Invoke-RestMethod -Uri "$NOTIFICATION/notifications/payment/$script:testPaymentId" -Method GET
    Pass "Notification lookup by payment_id"
    foreach ($n in $r) {
        $col = if ($n.status -eq "sent") { "Green" } else { "Yellow" }
        Write-Host "    [$($n.channel.ToUpper())] $($n.event) → $($n.recipient) [$($n.status)]" -ForegroundColor $col
    }
} catch { Warn "Notification lookup skipped" }

# Register a webhook
$script:webhookId = $null
try {
    $r = Invoke-RestMethod -Uri "$NOTIFICATION/webhooks/register" -Method POST -ContentType "application/json" -Body (@{
        merchant_id = "m_123"
        url         = "https://webhook.site/test-endpoint"
        description = "Test webhook"
        events      = @("*")
    } | ConvertTo-Json)
    $script:webhookId = $r.id
    Pass "Webhook registered"
    Data "Webhook ID" $r.id
    Data "Secret"     "$($r.secret.Substring(0,10))..."
} catch { Warn "Webhook registration skipped" }

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 7 — GATEWAY: MERCHANT ONBOARDING
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 7 · GATEWAY — MERCHANT REGISTRATION"

$mHeaders = @{
    "Content-Type"  = "application/json"
    "X-Secret-Key"  = $SECRET_KEY
    "Authorization" = "Bearer $($script:merchantJwt)"
}

$script:merchantId = $null
try {
    $r = Invoke-RestMethod -Uri "$GATEWAY/v1/merchant/register" -Method POST -Headers $mHeaders -Body (@{
        name          = "Test Shop $(Get-Date -Format 'HHmmss')"
        email         = "merchant@testshop.com"
        business_type = "ecommerce"
        country       = "US"
        currency      = "usd"
    } | ConvertTo-Json)
    $script:merchantId = $r.merchant_id ?? $r.id
    Pass "Merchant registered"
    Data "Merchant ID"  $script:merchantId
    Data "Status"       $r.status
} catch {
    Warn "Merchant register skipped (may already exist): $($_.ErrorDetails.Message)"
    $script:merchantId = "m_123"
    Info "Using default merchant_id: m_123"
}

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 8 — FULL PAYMENT FLOW (Auth → Capture)
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 8 · FULL PAYMENT FLOW — AUTHORIZE + CAPTURE"

$cHeaders = @{
    "Content-Type"      = "application/json"
    "X-Publishable-Key" = $PUBLISHABLE_KEY
    "Authorization"     = "Bearer $($script:customerJwt)"
}

# Step 1 — Create session
$script:sessionId = $null
try {
    $r = Invoke-RestMethod -Uri "$GATEWAY/v1/customer/payment_sessions" -Method POST -Headers $cHeaders -Body (@{
        amount      = 5000
        currency    = "usd"
        description = "System test order"
        capture     = $false               # auth-only first
        cart_id     = "cart_$(Get-Date -Format 'yyyyMMddHHmmss')"
    } | ConvertTo-Json)
    $script:sessionId = $r.session_id
    Pass "Payment session created"
    Data "Session ID" $script:sessionId
    Data "Expires"    $r.expires_at
} catch { Fail "Session creation failed: $($_.ErrorDetails.Message)"; $script:sessionId = $null }

# Step 2 — Tokenize card
$script:pmToken = $null
if ($script:sessionId) {
    try {
        $r = Invoke-RestMethod -Uri "$GATEWAY/v1/customer/payment_methods/tokenize" -Method POST -Headers $cHeaders -Body (@{
            card_number = "4242424242424242"
            exp_month   = 12
            exp_year    = 2026
            cvc         = "123"
        } | ConvertTo-Json)
        $script:pmToken = $r.payment_method_token
        Pass "Card tokenized"
        Data "Token"        "$($script:pmToken.Substring(0,12))..."
        Data "Card brand"   $r.brand
        Data "Last 4"       $r.last4
    } catch { Fail "Tokenize failed: $($_.ErrorDetails.Message)" }
}

# Step 3 — Confirm (authorize)
$script:paymentId = $null
if ($script:sessionId -and $script:pmToken) {
    try {
        $r = Invoke-RestMethod -Uri "$GATEWAY/v1/customer/payment_intents/confirm" -Method POST -Headers $cHeaders -Body (@{
            session_id           = $script:sessionId
            payment_method_token = $script:pmToken
        } | ConvertTo-Json)
        $script:paymentId = $r.payment.payment_id
        Pass "Payment authorized"
        Data "Payment ID" $script:paymentId
        Data "Status"     $r.payment.status
        Data "Amount"     "$($r.payment.amount / 100) $($r.payment.currency)"
    } catch { Fail "Confirm failed: $($_.ErrorDetails.Message)" }
}

# Step 4 — Capture (merchant action)
if ($script:paymentId) {
    Start-Sleep -Seconds 2
    try {
        $r = Invoke-RestMethod -Uri "$GATEWAY/v1/merchant/payments/$script:paymentId/capture" `
            -Method POST -Headers $mHeaders -Body (@{ amount = 5000 } | ConvertTo-Json)
        Pass "Payment captured"
        Data "Status"         $r.status
        Data "Captured amount" "$($r.amount / 100)"
    } catch { Warn "Capture skipped: $($_.ErrorDetails.Message)" }
}

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 9 — FULL PAYMENT FLOW (one-shot capture)
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 9 · FULL PAYMENT FLOW — IMMEDIATE CAPTURE"

$script:capturePaymentId = $null
try {
    # Session
    $sess = Invoke-RestMethod -Uri "$GATEWAY/v1/customer/payment_sessions" -Method POST -Headers $cHeaders -Body (@{
        amount      = 7500
        currency    = "usd"
        description = "One-shot capture test"
        capture     = $true
        cart_id     = "cart2_$(Get-Date -Format 'yyyyMMddHHmmss')"
    } | ConvertTo-Json)
    Pass "Session created: $($sess.session_id)"

    # Token
    $tok = Invoke-RestMethod -Uri "$GATEWAY/v1/customer/payment_methods/tokenize" -Method POST -Headers $cHeaders -Body (@{
        card_number = "4242424242424242"
        exp_month   = 12
        exp_year    = 2026
        cvc         = "123"
    } | ConvertTo-Json)
    Pass "Card tokenized: ...$($tok.last4)"

    # Confirm
    $pay = Invoke-RestMethod -Uri "$GATEWAY/v1/customer/payment_intents/confirm" -Method POST -Headers $cHeaders -Body (@{
        session_id           = $sess.session_id
        payment_method_token = $tok.payment_method_token
    } | ConvertTo-Json)
    $script:capturePaymentId = $pay.payment.payment_id
    Pass "Payment confirmed"
    Data "Payment ID" $script:capturePaymentId
    Data "Status"     $pay.payment.status
} catch { Fail "One-shot capture flow failed: $($_.ErrorDetails.Message)" }

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 10 — REFUND
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 10 · REFUND"

$refundTarget = $script:capturePaymentId ?? $script:paymentId
if ($refundTarget) {
    Start-Sleep -Seconds 2
    try {
        $r = Invoke-RestMethod -Uri "$GATEWAY/v1/merchant/payments/$refundTarget/refund" `
            -Method POST -Headers $mHeaders -Body (@{
                amount = 2500
                reason = "customer_request"
            } | ConvertTo-Json)
        Pass "Partial refund processed"
        Data "Refunded"        "$($r.refund_amount / 100)"
        Data "Payment status"  $r.status
    } catch { Warn "Refund skipped: $($_.ErrorDetails.Message)" }
} else { Warn "Refund skipped — no payment ID available" }

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 11 — VOID (auth-only payment)
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 11 · VOID AUTH-ONLY PAYMENT"

# Create a fresh auth-only payment to void
$script:voidPaymentId = $null
try {
    $sess = Invoke-RestMethod -Uri "$GATEWAY/v1/customer/payment_sessions" -Method POST -Headers $cHeaders -Body (@{
        amount  = 3000; currency = "usd"; description = "Void test"; capture = $false
        cart_id = "cart_void_$(Get-Date -Format 'yyyyMMddHHmmss')"
    } | ConvertTo-Json)

    $tok = Invoke-RestMethod -Uri "$GATEWAY/v1/customer/payment_methods/tokenize" -Method POST -Headers $cHeaders -Body (@{
        card_number = "4242424242424242"; exp_month = 12; exp_year = 2026; cvc = "123"
    } | ConvertTo-Json)

    $pay = Invoke-RestMethod -Uri "$GATEWAY/v1/customer/payment_intents/confirm" -Method POST -Headers $cHeaders -Body (@{
        session_id = $sess.session_id; payment_method_token = $tok.payment_method_token
    } | ConvertTo-Json)
    $script:voidPaymentId = $pay.payment.payment_id
    Pass "Auth-only payment created for void test: $script:voidPaymentId"
} catch { Warn "Could not create payment for void test" }

if ($script:voidPaymentId) {
    try {
        $r = Invoke-RestMethod -Uri "$GATEWAY/v1/merchant/payments/$script:voidPaymentId/void" `
            -Method POST -Headers $mHeaders -Body "{}"
        Pass "Payment voided"
        Data "Status" $r.status
    } catch { Warn "Void skipped: $($_.ErrorDetails.Message)" }
}

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 12 — PAYMENT LOOKUP & HISTORY
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 12 · PAYMENT LOOKUP & HISTORY"

$lookupId = $script:capturePaymentId ?? $script:paymentId
if ($lookupId) {
    # By payment ID (merchant)
    try {
        $r = Invoke-RestMethod -Uri "$GATEWAY/v1/merchant/payments/$lookupId" -Method GET -Headers $mHeaders
        Pass "Payment lookup by ID"
        Data "Status"   $r.status
        Data "Amount"   "$($r.amount / 100) $($r.currency)"
        Data "Created"  $r.created_at
    } catch { Warn "Payment lookup skipped" }

    # Payment list
    try {
        $r = Invoke-RestMethod -Uri "$GATEWAY/v1/merchant/payments?limit=5" -Method GET -Headers $mHeaders
        Pass "Payment list retrieved"
        Data "Count" ($r.data ?? $r).Count
    } catch { Warn "Payment list skipped" }
}

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 13 — LEDGER ENTRIES (post-payment)
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 13 · LEDGER — VERIFY ENTRIES WRITTEN"

if ($lookupId) {
    try {
        $r = Invoke-RestMethod -Uri "$LEDGER/entries/payment/$lookupId" -Method GET
        Pass "Ledger entries for payment"
        foreach ($e in $r) {
            Data "$($e.entry_type)" "amount=$($e.amount) account=$($e.account_id)"
        }
    } catch { Warn "Ledger entries lookup skipped" }
}

try {
    $r = Invoke-RestMethod -Uri "$LEDGER/accounts/acc_platform" -Method GET
    Pass "Platform account balance"
    Data "Balance" "$($r.balance) $($r.currency)"
} catch { Warn "Platform balance lookup skipped" }

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 14 — NOTIFICATIONS AUTO-FIRED
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 14 · NOTIFICATIONS AUTO-FIRED BY PAYMENT SERVICE"

if ($lookupId) {
    Start-Sleep -Seconds 3   # allow background tasks to complete
    try {
        $r = Invoke-RestMethod -Uri "$NOTIFICATION/notifications/payment/$lookupId" -Method GET
        if ($r.Count -gt 0) {
            Pass "Auto-notifications confirmed: $($r.Count) records"
            foreach ($n in $r) {
                $col = if ($n.status -eq "sent") { "Green" } else { "Red" }
                Write-Host "    [$($n.channel.ToUpper())] $($n.event) → $($n.recipient) [$($n.status)]" -ForegroundColor $col
            }
        } else {
            Warn "No auto-notifications found — verify NOTIFICATION_SERVICE_URL in payment-service env"
        }
    } catch { Warn "Notification auto-fire check skipped" }
}

# Final notification stats
try {
    $r = Invoke-RestMethod -Uri "$NOTIFICATION/stats" -Method GET
    Pass "Final notification stats"
    Data "Total"   $r.total_notifications
    Data "Sent"    $r.sent
    Data "Failed"  $r.failed
    Data "Webhooks" $r.total_webhooks
} catch { Warn "Final stats skipped" }

# ══════════════════════════════════════════════════════════════════════════════
# SECTION 15 — RATE LIMITING & SECURITY
# ══════════════════════════════════════════════════════════════════════════════
Write-Header "SECTION 15 · SECURITY — AUTH FAILURES"

# No token
try {
    Invoke-RestMethod -Uri "$GATEWAY/v1/merchant/payments" -Method GET `
        -Headers @{ "Content-Type"="application/json" } | Out-Null
    Warn "Expected 401 but got 200 — check auth middleware"
} catch {
    $code = $_.Exception.Response.StatusCode.value__
    if ($code -eq 401 -or $code -eq 403) { Pass "Unauthenticated request correctly rejected ($code)" }
    else { Warn "Unexpected status $code for unauth request" }
}

# Bad token
try {
    Invoke-RestMethod -Uri "$GATEWAY/v1/merchant/payments" -Method GET `
        -Headers @{ "Content-Type"="application/json"; "Authorization"="Bearer bad.token.here" } | Out-Null
    Warn "Expected 401 but got 200 — check token validation"
} catch {
    $code = $_.Exception.Response.StatusCode.value__
    if ($code -eq 401 -or $code -eq 403) { Pass "Invalid token correctly rejected ($code)" }
    else { Warn "Unexpected status $code for bad token" }
}

# ══════════════════════════════════════════════════════════════════════════════
# FINAL SUMMARY
# ══════════════════════════════════════════════════════════════════════════════
$total = $script:pass + $script:fail + $script:warn
Write-Host "`n╔$("═"*68)╗" -ForegroundColor Cyan
Write-Host "║                        FINAL RESULTS                             ║" -ForegroundColor Cyan
Write-Host "╚$("═"*68)╝" -ForegroundColor Cyan
Write-Host "`n  Total  : $total"           -ForegroundColor White
Write-Host "  Passed : $($script:pass)"   -ForegroundColor Green
Write-Host "  Warned : $($script:warn)"   -ForegroundColor Yellow
Write-Host "  Failed : $($script:fail)"   -ForegroundColor Red

if ($script:fail -eq 0) {
    Write-Host "`n  ✓ ALL CRITICAL TESTS PASSED" -ForegroundColor Green
    if ($script:warn -gt 0) {
        Write-Host "  ⚠ $($script:warn) warning(s) — non-critical, check endpoint names if needed" -ForegroundColor Yellow
    }
} else {
    Write-Host "`n  ✗ $($script:fail) FAILURE(S) — check logs:" -ForegroundColor Red
    Write-Host "    docker-compose logs --tail=30 <service-name>" -ForegroundColor Gray
}
Write-Host ""
